-- Count skill metadata as workspace records; private objects use the existing R2 meter.
CREATE TRIGGER storage_workspace_skill_insert AFTER INSERT ON workspace_skills BEGIN
 INSERT OR IGNORE INTO workspace_storage_accounts(workspace_id) VALUES(NEW.workspace_id);
 SELECT CASE WHEN EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+length(CAST(NEW.title AS BLOB))+length(CAST(NEW.source_filename AS BLOB))+length(CAST(NEW.description AS BLOB))+length(CAST(NEW.routing_json AS BLOB))+length(CAST(NEW.coverage_json AS BLOB))>CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+length(CAST(NEW.title AS BLOB))+length(CAST(NEW.source_filename AS BLOB))+length(CAST(NEW.description AS BLOB))+length(CAST(NEW.routing_json AS BLOB))+length(CAST(NEW.coverage_json AS BLOB)) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_workspace_skill_update AFTER UPDATE ON workspace_skills BEGIN
 SELECT CASE WHEN (length(CAST(NEW.title AS BLOB))+length(CAST(NEW.source_filename AS BLOB))+length(CAST(NEW.description AS BLOB))+length(CAST(NEW.routing_json AS BLOB))+length(CAST(NEW.coverage_json AS BLOB)))>(length(CAST(OLD.title AS BLOB))+length(CAST(OLD.source_filename AS BLOB))+length(CAST(OLD.description AS BLOB))+length(CAST(OLD.routing_json AS BLOB))+length(CAST(OLD.coverage_json AS BLOB))) AND EXISTS(SELECT 1 FROM workspace_storage_accounts WHERE workspace_id=NEW.workspace_id AND records_bytes+(length(CAST(NEW.title AS BLOB))+length(CAST(NEW.source_filename AS BLOB))+length(CAST(NEW.description AS BLOB))+length(CAST(NEW.routing_json AS BLOB))+length(CAST(NEW.coverage_json AS BLOB)))-(length(CAST(OLD.title AS BLOB))+length(CAST(OLD.source_filename AS BLOB))+length(CAST(OLD.description AS BLOB))+length(CAST(OLD.routing_json AS BLOB))+length(CAST(OLD.coverage_json AS BLOB)))>CASE WHEN plan_key='plus' AND paid_until>unixepoch() THEN plus_records_limit ELSE included_records_limit END) THEN RAISE(ABORT,'WORKSPACE_STORAGE_FULL') END;
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes+(length(CAST(NEW.title AS BLOB))+length(CAST(NEW.source_filename AS BLOB))+length(CAST(NEW.description AS BLOB))+length(CAST(NEW.routing_json AS BLOB))+length(CAST(NEW.coverage_json AS BLOB)))-(length(CAST(OLD.title AS BLOB))+length(CAST(OLD.source_filename AS BLOB))+length(CAST(OLD.description AS BLOB))+length(CAST(OLD.routing_json AS BLOB))+length(CAST(OLD.coverage_json AS BLOB))) WHERE workspace_id=NEW.workspace_id;
END;
CREATE TRIGGER storage_workspace_skill_delete AFTER DELETE ON workspace_skills BEGIN
 UPDATE workspace_storage_accounts SET records_bytes=records_bytes-(length(CAST(OLD.title AS BLOB))+length(CAST(OLD.source_filename AS BLOB))+length(CAST(OLD.description AS BLOB))+length(CAST(OLD.routing_json AS BLOB))+length(CAST(OLD.coverage_json AS BLOB))) WHERE workspace_id=OLD.workspace_id;
END;
